package com.greenTechnoClass.Day4;

public class MathFunctions {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		System.out.println(Math.abs(-890.9));
		System.out.println(Math.round(89.666));
		System.out.println(Math.ceil(45.4));
		System.out.println(Math.floor(46.6));
		System.out.println(Math.random());
		System.out.println(Math.round(Math.random()*10000));
		System.out.println(Math.sqrt(121));
		System.out.println(Math.PI);
	}

}
